/**
 * Ephemeris: apparent positions of the Sun, Moon, planets, Chiron and the
 * lunar node, and astrological houses, for an instant of Universal Time.
 *
 * An independent implementation built from published theories and data:
 *   - VSOP87 (Bretagnon & Francou 1988) for Mercury to Mars,
 *   - ELP 2000-82B (Chapront-Touzé & Chapront 1983, 1988) for the Moon,
 *   - numerical integration from JPL Horizons (DE441) states for Jupiter to
 *     Pluto and Chiron,
 *   - IAU 2006 precession and IAU 2000A_R06 nutation (IERS Conventions 2010).
 * The tables are generated by `scripts/ephemeris/`, which records how.
 */
import { apparentPosition } from './apparent.ts'
import type { Body } from './apparent.ts'
import { DEG, greenwichApparentSiderealTime, trueObliquity } from './frames.ts'
import { houses } from './houses.ts'
import type { HouseSystem, Houses } from './houses.ts'
import { centuriesSinceJ2000, julianDay, terrestrialTime } from './time.ts'

export { julianDay } from './time.ts'
export type { Body } from './apparent.ts'
export type { HouseSystem, Houses } from './houses.ts'

/**
 * Dates covered, as Julian days in UT: the years 1 to 3000 of the Gregorian
 * calendar, starting a day early so that 1 January of the year 1 is covered in
 * every time zone.
 */
export const EPHEMERIS_START = julianDay(1, 1, 1) - 1
export const EPHEMERIS_END = julianDay(3001, 1, 1)
/** Chiron's orbit is only well determined near the present: the years 1900 to 2099. */
export const CHIRON_START = julianDay(1900, 1, 1)
export const CHIRON_END = julianDay(2100, 1, 1)

/** Half-width of the interval over which speeds are measured, days (30 minutes). */
const SPEED_HALF_STEP = 1 / 48

/** Whether a body can be computed at a Julian day (UT). */
export function isAvailable(body: Body, jdUt: number): boolean {
  const [start, end] = body === 'Chiron' ? [CHIRON_START, CHIRON_END] : [EPHEMERIS_START, EPHEMERIS_END]
  return jdUt >= start && jdUt < end
}

function assertAvailable(body: Body, jdUt: number): void {
  if (isAvailable(body, jdUt)) return
  const years = body === 'Chiron' ? '1900–2099' : '1–3000'
  throw new RangeError(`Julian day ${jdUt} is outside the ephemeris range of ${body} (years ${years})`)
}

export interface EclipticPosition {
  /** Apparent geocentric ecliptic longitude of date, degrees in [0, 360). */
  longitude: number
  /** Apparent geocentric ecliptic latitude of date, degrees. */
  latitude: number
  /** Rate of change of the longitude, degrees per day; negative when retrograde. */
  speed: number
}

/**
 * Apparent position of a body at a Julian day in UT.
 *
 * @throws RangeError outside the range of the ephemeris (see `isAvailable`).
 */
export function eclipticPosition(body: Body, jdUt: number): EclipticPosition {
  assertAvailable(body, jdUt)
  const jdTt = terrestrialTime(jdUt)
  const { longitude, latitude } = apparentPosition(body, jdTt)

  const before = apparentPosition(body, jdTt - SPEED_HALF_STEP).longitude
  const after = apparentPosition(body, jdTt + SPEED_HALF_STEP).longitude
  let travelled = after - before
  if (travelled > Math.PI) travelled -= 2 * Math.PI
  if (travelled < -Math.PI) travelled += 2 * Math.PI

  return {
    longitude: longitude / DEG,
    latitude: latitude / DEG,
    speed: travelled / (2 * SPEED_HALF_STEP) / DEG,
  }
}

/**
 * House cusps and angles at a Julian day in UT.
 *
 * @param latitude  Geographic latitude, degrees (north positive).
 * @param longitude Geographic longitude, degrees (east positive).
 * @throws RangeError outside the range of the ephemeris or for an unknown system.
 */
export function housesAt(jdUt: number, latitude: number, longitude: number, system: HouseSystem): Houses {
  assertAvailable('Sun', jdUt)
  const t = centuriesSinceJ2000(terrestrialTime(jdUt))
  const ramc = greenwichApparentSiderealTime(jdUt, t) + longitude * DEG
  return houses(ramc, trueObliquity(t), latitude * DEG, system)
}
